const slugify=(s)=>String(s).trim().toLowerCase().replace(/<[^>]+>/g,'').replace(/[^\p{L}\p{N}\s-]/gu,'').replace(/\s+/g,'-').replace(/-+/g,'-')||'section';
function safeSource(raw){const value=String(raw||'').trim();if(!value||/^(?:https?:|data:|javascript:|file:)/i.test(value)||value.includes('..'))throw new Error('Invalid Markdown source');if(value.startsWith('//'))throw new Error('Invalid Markdown source');return value;}
const isEn=()=>document.querySelector('lri-site-shell')?.locale==='en'||document.documentElement.lang.toLowerCase().startsWith('en');
const labels=()=>isEn()?{loading:'Loading report…',print:'Print',top:'Top',contents:'Contents',aria:'Report contents',error:'Report rendering failed'}:{loading:'正在加载报告…',print:'打印',top:'回到顶部',contents:'目录',aria:'报告目录',error:'报告渲染失败'};
function buildToc(root,toc,{shellOutline=false}={}){const seen=new Map();const headings=[...root.querySelectorAll('h2,h3')];toc.innerHTML='';for(const h of headings){let id=slugify(h.textContent);const n=(seen.get(id)||0)+1;seen.set(id,n);if(n>1)id=`${id}-${n}`;h.id=id;const level=h.tagName.slice(1);if(shellOutline){h.dataset.sectionId=id;h.dataset.sectionLabel=h.textContent;h.dataset.sectionLevel=level;}const a=document.createElement('a');a.href=`#${id}`;a.textContent=h.textContent;a.dataset.level=level;toc.append(a);}const observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){toc.querySelectorAll('a').forEach(a=>a.classList.toggle('is-active',a.hash===`#${e.target.id}`));}}},{rootMargin:'-15% 0px -70%'});headings.forEach(h=>observer.observe(h));if(shellOutline)document.dispatchEvent(new CustomEvent('lri:sections-changed'));}
function hardenLinks(root){root.querySelectorAll('a[href]').forEach(a=>{const href=a.getAttribute('href')||'';if(/^https?:\/\//i.test(href)){a.target='_blank';a.rel='noopener noreferrer';}});}
function wrapTables(root){root.querySelectorAll('table').forEach(table=>{if(table.parentElement?.classList.contains('md-table-scroll'))return;const wrap=document.createElement('div');wrap.className='md-table-scroll';wrap.setAttribute('tabindex','0');table.parentNode.insertBefore(wrap,table);wrap.append(table);});}
function setProgress(){const max=document.documentElement.scrollHeight-innerHeight;const pct=max>0?Math.min(100,scrollY/max*100):0;document.documentElement.style.setProperty('--md-progress',`${pct}%`);}
function applyChromeLocale(host){const l=labels();const loading=host.querySelector('.md-loading');if(loading)loading.textContent=l.loading;const p=host.querySelector('[data-md-print]');if(p)p.textContent=l.print;const t=host.querySelector('[data-md-top]');if(t)t.textContent=l.top;const title=host.querySelector('.md-toc-title');if(title)title.textContent=l.contents;host.querySelector('.md-toc')?.setAttribute('aria-label',l.aria);const err=host.querySelector('.md-error strong');if(err)err.textContent=l.error;}
export async function renderMarkdownReader(options={}){const host=document.querySelector(options.host||'[data-markdown-reader]');if(!host)return;try{const src=safeSource(options.src||host.dataset.markdownSrc||new URLSearchParams(location.search).get('src'));host.innerHTML='<div class="md-loading"></div>';applyChromeLocale(host);const res=await fetch(src,{cache:'no-store'});if(!res.ok)throw new Error(`HTTP ${res.status}`);const markdown=await res.text();if(!globalThis.marked||!globalThis.DOMPurify)throw new Error('renderer unavailable');marked.setOptions({gfm:true,breaks:false});const html=DOMPurify.sanitize(marked.parse(markdown),{USE_PROFILES:{html:true},ADD_ATTR:['target','rel']});host.innerHTML=`<div class="md-progress" aria-hidden="true"></div><div class="md-shell"><aside class="md-sidebar"><div class="md-brand"><span class="md-brand-mark"></span><span>LRI Insight</span></div><div class="md-meta">${src.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</div><div class="md-tools"><button class="md-tool" data-md-print></button><button class="md-tool" data-md-top></button></div><div class="md-toc-title"></div><nav class="md-toc"></nav></aside><main class="md-stage"><article class="md-paper"><div class="md-document"></div></article></main></div>`;const doc=host.querySelector('.md-document');doc.innerHTML=html;hardenLinks(doc);wrapTables(doc);buildToc(doc,host.querySelector('.md-toc'),{shellOutline:options.shellOutline===true});applyChromeLocale(host);host.querySelector('[data-md-print]').onclick=()=>print();host.querySelector('[data-md-top]').onclick=()=>scrollTo({top:0,behavior:'smooth'});addEventListener('scroll',setProgress,{passive:true});setProgress();document.title=`${doc.querySelector('h1')?.textContent||'LRI Insight'} · LRI`;const onLocale=()=>applyChromeLocale(host);document.addEventListener('lri:locale-change',onLocale,{signal:options.signal});return {host,doc,applyLocale:onLocale};}catch(error){host.innerHTML=`<div class="md-error"><strong></strong><p>${String(error.message||error)}</p></div>`;applyChromeLocale(host);}}

